-- Schema transcribed from the read-only production sqlite_schema inspection.
-- No customer data. Used only in local, in-memory tests.
CREATE TABLE leads (
id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT DEFAULT '', email TEXT DEFAULT '', phone TEXT DEFAULT '', service TEXT DEFAULT '', message TEXT DEFAULT '', source TEXT DEFAULT '', medium TEXT DEFAULT '', campaign TEXT DEFAULT '', landing_page TEXT DEFAULT '',
status TEXT NOT NULL DEFAULT 'New' CHECK(status IN ('New','Contacted','Quote Sent','Won','Lost')), quote_amount REAL NOT NULL DEFAULT 0, revenue REAL NOT NULL DEFAULT 0, notes TEXT DEFAULT '', visitor_id TEXT DEFAULT '',
created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
normalized_email TEXT NOT NULL DEFAULT '', normalized_phone TEXT NOT NULL DEFAULT '', submission_count INTEGER NOT NULL DEFAULT 0, last_contact_at TEXT NOT NULL DEFAULT '', last_page TEXT NOT NULL DEFAULT '', last_form TEXT NOT NULL DEFAULT '', referrer TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', term TEXT NOT NULL DEFAULT '');
CREATE TABLE inquiries (id TEXT PRIMARY KEY, lead_id INTEGER NOT NULL REFERENCES leads(id), service TEXT NOT NULL DEFAULT '', page TEXT NOT NULL DEFAULT '', form TEXT NOT NULL DEFAULT '', landing_page TEXT NOT NULL DEFAULT '', referrer TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', medium TEXT NOT NULL DEFAULT '', campaign TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', term TEXT NOT NULL DEFAULT '', message TEXT NOT NULL DEFAULT '', details TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE quote_requests (id TEXT PRIMARY KEY REFERENCES inquiries(id), lead_id INTEGER NOT NULL REFERENCES leads(id), service TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Requested' CHECK(status IN ('Requested','Quoted','Accepted','Declined')), amount REAL DEFAULT NULL CHECK(amount IS NULL OR amount>=0), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE jobs (id TEXT PRIMARY KEY, lead_id INTEGER REFERENCES leads(id), customer TEXT NOT NULL, service TEXT NOT NULL, quoted_cents INTEGER CHECK(quoted_cents IS NULL OR quoted_cents>=0), collected_cents INTEGER NOT NULL CHECK(collected_cents>=0), payment_status TEXT NOT NULL CHECK(payment_status IN ('Paid','Partial','Unpaid')), payment_method TEXT NOT NULL CHECK(payment_method IN ('Cash','Card','Check','Venmo','Other')), job_date TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), deleted_at TEXT);
CREATE TABLE ledger_leads (lead_id INTEGER PRIMARY KEY REFERENCES leads(id), prior_status TEXT NOT NULL, promoted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE operations_schedule (id TEXT PRIMARY KEY, lead_id TEXT, customer TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', service TEXT NOT NULL, service_note TEXT NOT NULL DEFAULT '', job_date TEXT NOT NULL, start_time TEXT NOT NULL DEFAULT '', end_time TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Scheduled', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE operations_reminders (id TEXT PRIMARY KEY, lead_id TEXT, customer TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, due_date TEXT NOT NULL, due_time TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', completed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, visitor_id TEXT NOT NULL, event TEXT NOT NULL, page TEXT DEFAULT '', title TEXT DEFAULT '', label TEXT DEFAULT '', referrer TEXT DEFAULT '', source TEXT DEFAULT '', medium TEXT DEFAULT '', campaign TEXT DEFAULT '', content TEXT DEFAULT '', term TEXT DEFAULT '', country TEXT DEFAULT '', region TEXT DEFAULT '', city TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), event_id TEXT, landing_page TEXT NOT NULL DEFAULT '', form TEXT NOT NULL DEFAULT '', service TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX idx_events_event_id ON events(event_id);
CREATE TABLE rate_limits (bucket TEXT PRIMARY KEY, hits INTEGER NOT NULL DEFAULT 0, reset_at INTEGER NOT NULL);
CREATE TABLE admin_summary_cache (key TEXT PRIMARY KEY, valid_on TEXT NOT NULL, value TEXT NOT NULL);
CREATE TRIGGER summary_jobs_delete AFTER DELETE ON jobs BEGIN DELETE FROM admin_summary_cache; END;
CREATE TRIGGER summary_jobs_insert AFTER INSERT ON jobs BEGIN DELETE FROM admin_summary_cache; END;
CREATE TRIGGER summary_jobs_update AFTER UPDATE OF quoted_cents,collected_cents,payment_status,job_date,deleted_at ON jobs BEGIN DELETE FROM admin_summary_cache; END;
CREATE TRIGGER summary_leads_delete AFTER DELETE ON leads BEGIN DELETE FROM admin_summary_cache; END;
CREATE TRIGGER summary_leads_insert AFTER INSERT ON leads BEGIN DELETE FROM admin_summary_cache; END;
CREATE TRIGGER summary_leads_update AFTER UPDATE OF status,quote_amount,revenue,created_at ON leads WHEN OLD.status IS NOT NEW.status OR OLD.quote_amount IS NOT NEW.quote_amount OR OLD.revenue IS NOT NEW.revenue OR OLD.created_at IS NOT NEW.created_at BEGIN DELETE FROM admin_summary_cache; END;
CREATE TRIGGER summary_ledger_delete AFTER DELETE ON ledger_leads BEGIN DELETE FROM admin_summary_cache; END;
CREATE TRIGGER summary_ledger_insert AFTER INSERT ON ledger_leads BEGIN DELETE FROM admin_summary_cache; END;
CREATE TRIGGER summary_ledger_update AFTER UPDATE OF lead_id ON ledger_leads BEGIN DELETE FROM admin_summary_cache; END;
